final class Trie {
    private final class Node { var children: [Character: Node] = [:]; var isWord = false }
    private let root = Node()

    func insert(_ word: String) {
        var node = root
        for c in word {
            if node.children[c] == nil { node.children[c] = Node() }
            node = node.children[c]!
        }
        node.isWord = true
    }
    func search(_ word: String) -> Bool { find(word)?.isWord ?? false }
    func startsWith(_ prefix: String) -> Bool { find(prefix) != nil }

    private func find(_ s: String) -> Node? {
        var node = root
        for c in s { guard let next = node.children[c] else { return nil }; node = next }
        return node
    }
}
